  40:  * {@link ContentProvider ContentProvider's} onCreate() methods are "called for all registered
  41:  * content providers on the application main thread at application launch time." This means we
  42:  * can use a content provider to register for Activity lifecycle callbacks before any activities
  43:  * have started, for installing the CarUi base layout into all activities.
  44:  */
  45: public class CarUiInstaller extends ContentProvider {
  46: 
  47:     private static final String TAG = "CarUiInstaller";
  48:     private static final String CAR_UI_INSET_LEFT = "CAR_UI_INSET_LEFT";
  49:     private static final String CAR_UI_INSET_RIGHT = "CAR_UI_INSET_RIGHT";
  50:     private static final String CAR_UI_INSET_TOP = "CAR_UI_INSET_TOP";
  51:     private static final String CAR_UI_INSET_BOTTOM = "CAR_UI_INSET_BOTTOM";
  52: 
  53:     private static final boolean IS_DEBUG_DEVICE =
  54:             Build.TYPE.toLowerCase(Locale.ROOT).contains("debug")
  55:                     || Build.TYPE.toLowerCase(Locale.ROOT).equals("eng");
  56: 
  57:     @Override
  58:     public boolean onCreate() {
  59:         Context context = getContext();
  60:         if (context == null) {
  61:             Log.e(TAG, "CarUiInstaller had a null context!");
  62:             return false;
  63:         }
  64:         Log.i(TAG, "CarUiInstaller started for " + context.getPackageName());
  65: 
  66:         Application application = (Application) context.getApplicationContext();
  67:         application.registerActivityLifecycleCallbacks(
  68:                 new Application.ActivityLifecycleCallbacks() {
  69:                     private Insets mInsets = null;
  70:                     private boolean mIsActivityStartedForFirstTime = false;
  71: 
  72:                     @Override
  73:                     public void onActivityCreated(Activity activity, Bundle savedInstanceState) {
  74:                         if (activity.getClassLoader()
  75:                                 .equals(CarUiInstaller.class.getClassLoader())) {
  76:                             BaseLayoutController.build(activity);
  77:                         } else {
  78:                             callBaseLayoutControllerMethod("build", activity);
  79:                         }
  80: 
  81:                         if (savedInstanceState != null) {
  82:                             int inset_left = savedInstanceState.getInt(CAR_UI_INSET_LEFT);
  83:                             int inset_top = savedInstanceState.getInt(CAR_UI_INSET_TOP);
  84:                             int inset_right = savedInstanceState.getInt(CAR_UI_INSET_RIGHT);
  85:                             int inset_bottom = savedInstanceState.getInt(CAR_UI_INSET_BOTTOM);
  86:                             mInsets = new Insets(inset_left, inset_top, inset_right, inset_bottom);
  87:                         }
  88: 
  89:                         mIsActivityStartedForFirstTime = true;
  90:                     }
  91: 
  92:                     @Override
  93:                     public void onActivityPostStarted(Activity activity) {
  94:                         BaseLayoutController controller = getBaseLayoutController(activity);
  95:                         if (mInsets != null && controller != null
  96:                                 && mIsActivityStartedForFirstTime) {
  97:                             controller.dispatchNewInsets(mInsets);
  98:                             mIsActivityStartedForFirstTime = false;
  99:                         }
 100:                     }
 101: 
 102:                     @Override
 103:                     public void onActivityStarted(Activity activity) {
 104:                     }
 105: 
 106:                     @Override
 107:                     public void onActivityResumed(Activity activity) {
 108:                     }
 109: 
 110:                     @Override
 111:                     public void onActivityPaused(Activity activity) {
 112:                     }
 113: 
 114:                     @Override
 115:                     public void onActivityStopped(Activity activity) {
 116:                     }
