 119:                     public void onActivitySaveInstanceState(Activity activity, Bundle outState) {
 120:                         BaseLayoutController controller = getBaseLayoutController(activity);
 121:                         if (controller != null) {
 122:                             Insets insets = controller.getInsets();
 123:                             outState.putInt(CAR_UI_INSET_LEFT, insets.getLeft());
 124:                             outState.putInt(CAR_UI_INSET_TOP, insets.getTop());
 125:                             outState.putInt(CAR_UI_INSET_RIGHT, insets.getRight());
 126:                             outState.putInt(CAR_UI_INSET_BOTTOM, insets.getBottom());
 127:                         }
 128:                     }
