 133:                                 .equals(CarUiInstaller.class.getClassLoader())) {
 134:                             BaseLayoutController.destroy(activity);
 135:                         } else {
 136:                             callBaseLayoutControllerMethod("destroy", activity);
 137:                         }
 138:                     }
 139:                 });
