 130:      * This method installs the base layout *around* the provided view. As a result, this view
 131:      * must have a parent ViewGroup.
 132:      *
 133:      * When using this method, you can't use the other activity-based methods.
 134:      * ({@link #requireToolbar(Activity)}, {@link #requireInsets(Activity)}, ect.)
 135:      *
 136:      * @param view The view to wrap inside a base layout.
 137:      * @param hasToolbar if there should be a toolbar in the base layout.
 138:      * @return The {@link ToolbarController}, which will be null if hasToolbar is false.
 139:      */
 140:     @Nullable
 141:     public static ToolbarController installBaseLayoutAround(
 142:             View view,
 143:             InsetsChangedListener insetsChangedListener,
 144:             boolean hasToolbar) {
 145:         Pair<ToolbarController, InsetsUpdater> results =
 146:                 BaseLayoutController.installBaseLayoutAround(null, view, hasToolbar);
 147: 
 148:         Objects.requireNonNull(results.second)
 149:                 .replaceInsetsChangedListenerWith(insetsChangedListener);
 150: 
 151:         return results.first;
 152:     }
 153: 
 154:     /* package */ static BaseLayoutController getBaseLayoutController(Activity activity) {
 155:         if (activity.getClassLoader().equals(CarUi.class.getClassLoader())) {
 156:             return BaseLayoutController.getBaseLayout(activity);
 157:         } else {
 158:             // Note: (b/156532465)
 159:             // The usage of the alternate classloader is to accommodate GMSCore.
 160:             // Some activities are loaded dynamically from external modules.
 161:             try {
 162:                 Class<?> baseLayoutControllerClass = activity.getClassLoader()
 163:                         .loadClass(BaseLayoutController.class.getName());
 164:                 Method method = baseLayoutControllerClass
 165:                         .getDeclaredMethod("getBaseLayout", Activity.class);
 166:                 return (BaseLayoutController) method.invoke(null, activity);
 167:             } catch (ReflectiveOperationException e) {
 168:                 throw new RuntimeException(e);
 169:             }
 170:         }
 171:     }
 172: }
