 156:     /**
 157:      * This test will use {@link CarPropertyManager#setProperty(Class, int, int, Object)} to turn
 158:      * on the HVAC_PROWER and then let Default VHAL to generate HVAC data and verify on-the-fly
 159:      * in the test. It is simulating the HVAC actions coming from hard buttons in a car.
 160:      * @throws Exception
 161:      */
 162:     @Test
 163:     public void testHvacHardButtonOperations() throws Exception {
 164: 
 165:         Log.d(TAG, "Prepare HVAC test data");
 166:         List<CarPropertyValue> expectedEvents = getExpectedEvents(CAR_HVAC_TEST_JSON);
 167:         List<CarPropertyValue> expectedSetEvents = getExpectedEvents(CAR_HVAC_TEST_SET_JSON);
 168: 
 169:         CarPropertyManager propMgr = (CarPropertyManager) mCar.getCarManager(Car.PROPERTY_SERVICE);
 170:         assertNotNull("CarPropertyManager is null", propMgr);
 171: 
 172:         // test set method from android side
 173:         for (CarPropertyValue expectedEvent : expectedSetEvents) {
 174:             Class valueClass = expectedEvent.getValue().getClass();
 175:             propMgr.setProperty(valueClass,
 176:                     expectedEvent.getPropertyId(),
 177:                     expectedEvent.getAreaId(),
 178:                     expectedEvent.getValue());
 179:             Thread.sleep(WAIT_FOR_CALLBACK);
 180:             CarPropertyValue receivedEvent = propMgr.getProperty(valueClass,
 181:                     expectedEvent.getPropertyId(), expectedEvent.getAreaId());
 182:             assertTrue("Mismatched events, expected: " + expectedEvent + ", received: "
 183:                     + receivedEvent, Utils.areCarPropertyValuesEqual(expectedEvent, receivedEvent));
 184:         }
 185: 
 186:         // test that set from vehicle side will trigger callback to android
 187:         VhalEventVerifier verifier = new VhalEventVerifier(expectedEvents);
 188:         ArraySet<Integer> props = new ArraySet<>();
 189:         for (CarPropertyValue event : expectedEvents) {
 190:                 props.add(event.getPropertyId());
 191:         }
 192:         CarPropertyEventReceiver receiver =
 193:                 new CarPropertyEventReceiver(verifier);
 194:         for (Integer prop : props) {
 195:             propMgr.registerCallback(receiver, prop, 0);
 196:         }
 197:         Thread.sleep(WAIT_FOR_CALLBACK);
 198:         receiver.startVerifying();
 199:         injectEventFromVehicleSide(expectedEvents, propMgr);
 200:         verifier.waitForEnd(TEST_TIME_OUT.toMillis());
 201:         propMgr.unregisterCallback(receiver);
 202: 
 203:         assertTrue("Detected mismatched events: " + verifier.getResultString(),
 204:                     verifier.getMismatchedEvents().isEmpty());
 205:     }
