 947:     // Handles ServiceSpecificException in CarService for R and later version.
 948:     private <T> T handleCarServiceSpecificException(
 949:             ServiceSpecificException e, int propId, int areaId, T returnValue) {
 950:         // We are not passing the error message down, so log it here.
 951:         Log.w(TAG, "received ServiceSpecificException: " + e);
 952:         int errorCode = e.errorCode;
 953:         switch (errorCode) {
 954:             case VehicleHalStatusCode.STATUS_NOT_AVAILABLE:
 955:                 throw new PropertyNotAvailableException(propId, areaId);
 956:             case VehicleHalStatusCode.STATUS_TRY_AGAIN:
 957:                 throw new PropertyNotAvailableAndRetryException(propId, areaId);
 958:             case VehicleHalStatusCode.STATUS_ACCESS_DENIED:
 959:                 throw new PropertyAccessDeniedSecurityException(propId, areaId);
 960:             case VehicleHalStatusCode.STATUS_INTERNAL_ERROR:
 961:                 throw new CarInternalErrorException(propId, areaId);
 962:             default:
 963:                 Log.e(TAG, "Invalid errorCode: " + errorCode + " in CarService");
 964:         }
 965:         return returnValue;
 966:     }
